@import "@fontsource-variable/space-grotesk";
@import "@fontsource/space-mono/400.css";
@import "@fontsource-variable/inter";

/* Light sibling: a paper-grey page (#efefed), white cards, near-black text, mid-grey links,
   the same signal yellow and the bus tones, a touch deeper so they hold on a pale page. */
:root {
  --background: oklch(0.952 0.003 106.4);
  --foreground: oklch(0.18 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.18 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.18 0 0);
  --primary: oklch(0.816 0.164 82.8);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.912 0.004 106.5);
  --secondary-foreground: oklch(0.18 0 0);
  --muted: oklch(0.87 0.004 106.5);
  --muted-foreground: oklch(0.5 0 0);
  --accent: oklch(0.912 0.004 106.5);
  --accent-foreground: oklch(0.18 0 0);
  --destructive: oklch(0.577 0.215 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.18 0 0 / 18%);
  --input: oklch(0.18 0 0 / 30%);
  --ring: oklch(0.732 0.151 80.5);
  --highlight: oklch(0.732 0.151 80.5);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.816 0.164 82.8);
  --chart-1: oklch(0.56 0.231 307.1);
  --chart-2: oklch(0.62 0.17 256.1);
  --chart-3: oklch(0.66 0.192 45.6);
  --chart-4: oklch(0.64 0.158 160.8);
  --chart-5: oklch(0.816 0.164 82.8);
  --sidebar: oklch(1 0 0);
  --sidebar-foreground: oklch(0.18 0 0);
  --sidebar-primary: oklch(0.816 0.164 82.8);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(0.912 0.004 106.5);
  --sidebar-accent-foreground: oklch(0.18 0 0);
  --sidebar-border: oklch(0.18 0 0 / 18%);
  --sidebar-ring: oklch(0.732 0.151 80.5);

  --typeface-body: "Inter Variable", Inter, Arial, sans-serif;
  --typeface-display: "Space Grotesk Variable", "Space Grotesk", Arial, sans-serif;
  --typeface-mono: "Space Mono", ui-monospace, Menlo, Consolas, monospace;
  --radius: 0px;
  --page-width: 120rem;
  --page-gutter: 1rem;
  /* 80px on a 390px phone, 160px at 1440 */
  --section-y: clamp(5rem, 3.15rem + 7.62vw, 10rem);
}

/* Faithful mode: charcoal bands (#1a1a1a), pure-black platform band and tiles (#000), white
   text, #808080 links and notes, signal yellow (#f6b717) buttons, white-15% hairlines, the bus
   tones purple #a145e4, blue #4e98f9, orange #f76b0e and green #0dc182. */
.dark {
  --background: oklch(0.218 0 0);
  --foreground: oklch(1 0 0);
  --card: oklch(0 0 0);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.218 0 0);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(0.816 0.164 82.8);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0 0 0);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.321 0 0);
  --muted-foreground: oklch(0.6 0 0);
  --accent: oklch(0.269 0 0);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.65 0.2 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 15%);
  --input: oklch(1 0 0 / 30%);
  --ring: oklch(0.816 0.164 82.8);
  --highlight: oklch(0.816 0.164 82.8);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.816 0.164 82.8);
  --chart-1: oklch(0.587 0.231 307.1);
  --chart-2: oklch(0.678 0.162 256.1);
  --chart-3: oklch(0.691 0.192 45.6);
  --chart-4: oklch(0.717 0.158 160.8);
  --chart-5: oklch(0.816 0.164 82.8);
  --sidebar: oklch(0 0 0);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(0.816 0.164 82.8);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(0.269 0 0);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 15%);
  --sidebar-ring: oklch(0.816 0.164 82.8);
}
